import { readFile } from 'node:fs/promises'

import { inject } from '@adonisjs/core'
import app from '@adonisjs/core/services/app'
import logger from '@adonisjs/core/services/logger'
import { left, right, type Either } from '@interclasse/shared'

import HTTPException from '#exceptions/http.exception'

type Response = Either<HTTPException, string>

/**
 * The OpenAPI document as it is on disk.
 *
 * Read on the first request and kept in memory: it is an artifact generated by
 * `node ace openapi:generate` and committed, so in production it does not change
 * while the process lives. Reading per request would only spend I/O.
 */
@inject()
export default class DocumentationOpenapiShowUseCase {
  private static specification: string | undefined

  async execute(): Promise<Response> {
    try {
      if (!DocumentationOpenapiShowUseCase.specification) {
        DocumentationOpenapiShowUseCase.specification = await readFile(
          app.makePath('openapi.json'),
          'utf-8',
        )
      }

      return right(DocumentationOpenapiShowUseCase.specification)
    } catch (error) {
      logger.error({ err: error }, '[documentation/openapi > show][error]')

      return left(
        HTTPException.InternalServerError(
          'Erro interno do servidor',
          'DOCUMENTATION_OPENAPI_SHOW_ERROR',
        ),
      )
    }
  }
}
